INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l43','come up against','',NULL,'/kʌm ʌp əˈɡenst/','Here we come up against the hardest obstacle.','在这里我们撞上了最难的障碍。','They came up against fierce opposition.','他们遭遇了激烈的反对。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l43','give off','',NULL,'/ɡɪv ɔːf/','The frequency is naturally given off by hydrogen atoms.','这一频率是氢原子自然发出的。','The flowers give off a sweet scent.','这些花散发出甜甜的香气。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l43','on average','',NULL,'/ɑːn ˈævərɪdʒ/','On average, our neighbors might be a hundred light years away.','平均而言,我们的邻居也许在一百光年之外。','He reads two books a month on average.','他平均每月读两本书。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l43','in the hope of','',NULL,'/ɪn ðə hoʊp ʌv/','Wandering the streets in the hope of a chance encounter.','在街头游荡,指望一次偶然的相遇。','She wrote again in the hope of a reply.','她再次去信,盼着有个回音。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp1','choice','{"stem":"\"Other stars are ___ to have planets like our own.\"(be ___ to do 表‘必定/注定要’,填那个过去分词)","options":["bind","bounded","bound","binding"],"answer_index":2,"stem_cn":"别的恒星必定也有像我们这样的行星。","explanation_cn":"be bound to do,‘必定/注定要…’;填过去分词 bound。✓ are bound to have planets. ✗ bounded(边界)/ binding(约束的)/ bind(原形):此结构用 bound。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp1','choice','{"stem":"\"Given so many planets, intelligent life is ___ to arise somewhere.\"(‘必定/注定要…’这个结构,填那个过去分词)","options":["bound","bounded","binding","bind"],"answer_index":0,"stem_cn":"有这么多行星,智慧生命必定会在某处出现。","explanation_cn":"be bound to do,‘必定…’;填 bound。✓ is bound to arise somewhere. ✗ bounded / binding / bind:此结构用 bound。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp1','choice','{"stem":"\"Such a signal is bound ___ be known to any radio astronomer.\"(be bound + 不定式,填不定式记号)","options":["that","/","for","to"],"answer_index":3,"stem_cn":"这样的信号必定为任何射电天文学家所知。","explanation_cn":"be bound + 不定式;填不定式记号 to。✓ is bound to be known. ✗ 省略(不可省 to)/ that / for:bound 后接 to do。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp2','choice','{"stem":"\"Visitors ___ have come to Earth millions of years ago.\"(对过去的推测‘可能已经做过…’,填那个情态动词)","options":["will","may","shall","does"],"answer_index":1,"stem_cn":"访客可能在数百万年前就来过地球。","explanation_cn":"对过去的推测‘可能已经…’= may + have + 过去分词;填情态动词 may。✓ may have come long ago. ✗ will / shall / does:对过去推测用 may have done。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp2','choice','{"stem":"\"A superior civilization ___ have left a messenger behind.\"(‘可能已经…’对过去推测,填情态动词)","options":["shall","does","will","might"],"answer_index":3,"stem_cn":"某个高等文明可能已留下一个信使。","explanation_cn":"对过去的推测‘可能已经…’;填情态动词 might。✓ might have left a messenger. ✗ will / shall / does:对过去推测用 might have done。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp2','choice','{"stem":"\"They may have ___ our primitive state uninteresting.\"(may have + 过去分词,填‘发现’那个动词的过去分词)","options":["finds","find","found","finding"],"answer_index":2,"stem_cn":"他们可能已觉得我们的原始状态毫无趣味。","explanation_cn":"may have + 过去分词;填 find 的过去分词 found。✓ may have found our state uninteresting. ✗ find(原形)/ finds / finding:have 后用过去分词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp3','choice','{"stem":"\"So ___ is the number of planets that intelligent life must exist.\"(so + 形容词 + 倒装,填那个形容词)","options":["vast","vastly","vaster","vastest"],"answer_index":0,"stem_cn":"行星的数目如此之多,以致智慧生命必然存在。","explanation_cn":"so + 形容词 + 倒装;填形容词原级 vast。✓ So vast is the number that … ✗ vastly(副词)/ vaster(比较级)/ vastest(最高级):倒装句中用形容词原级。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp3','choice','{"stem":"\"So ___ are the distances that radio waves take centuries to cross.\"(so + 形容词 + 倒装,填那个形容词)","options":["greatly","greater","greatest","great"],"answer_index":3,"stem_cn":"距离如此之大,以致无线电波要几个世纪才能穿越。","explanation_cn":"so + 形容词 + 倒装;填形容词原级 great。✓ So great are the distances that … ✗ greatly(副词)/ greater / greatest:此处用原级 great。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp3','choice','{"stem":"\"So vast ___ the universe that countless worlds may hold life.\"(so + 形容词 + 倒装,填倒装后提前的 be 动词)","options":["is","being","has","does"],"answer_index":0,"stem_cn":"宇宙如此浩瀚,以致无数世界都可能孕育生命。","explanation_cn":"so + 形容词提前引起倒装;主语 the universe 单数,be 动词提前用 is。✓ So vast is the universe that … ✗ does / has / being:倒装提前的是 be 动词 is。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp4','choice','{"stem":"\"Our rockets cannot reach the nearest star, ___ galaxies far beyond.\"(‘更不用说…’,填那个词组)","options":["as well as","rather than","let alone","along with"],"answer_index":2,"stem_cn":"我们的火箭连最近的恒星都到不了,更别提遥远的星系。","explanation_cn":"‘更不用说…’用 let alone,前句为否定。✓ cannot reach the star, let alone galaxies. ✗ as well as 以及 / rather than 而不是 / along with 连同:‘更不用说’用 let alone。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp4','choice','{"stem":"\"He has never left his own town, ___ traveled to another planet.\"(‘更不用说…’,填那个词组)","options":["rather than","together with","as well as","let alone"],"answer_index":3,"stem_cn":"他连自己的镇都没离开过,更别说去别的星球。","explanation_cn":"‘更不用说…’用 let alone。✓ never left his town, let alone another planet. ✗ as well as / rather than / together with:‘更不用说’用 let alone。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp4','choice','{"stem":"\"We can barely orbit our own world, ___ cross the stars.\"(‘更不用说…’,填那个词组)","options":["apart from","let alone","instead of","as well as"],"answer_index":1,"stem_cn":"我们勉强能绕自己的星球飞行,更别说穿越群星。","explanation_cn":"‘更不用说…’用 let alone。✓ can barely orbit our world, let alone cross the stars. ✗ as well as / instead of / apart from:‘更不用说’用 let alone。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp5','choice','{"stem":"\"___ was not long before its use for interstellar signals was suggested.\"(‘不久就…’,填句首作形式主语的那个词)","options":["That","There","It","This"],"answer_index":2,"stem_cn":"不久,人们就提议用它来做星际通讯。","explanation_cn":"it was not long before …,‘不久就…’;句首用形式主语 It。✓ It was not long before its use was suggested. ✗ There / That / This:此惯用句型句首用 It。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp5','choice','{"stem":"\"It was not long ___ scientists suggested using this frequency.\"(‘过了不久就…’,填 not long 后那个连词)","options":["since","before","until","after"],"answer_index":1,"stem_cn":"没过多久,科学家就提议使用这一频率。","explanation_cn":"it was not long before …;not long 后接连词 before。✓ It was not long before scientists suggested it. ✗ after / until / since:此句型用 before。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp5','choice','{"stem":"\"Once the wavelength had been found, it was not long before the whole world ___ about it.\"(it was not long before + 从句,填‘得知’那个动词的过去式)","options":["knowing","know","known","knew"],"answer_index":3,"stem_cn":"一旦发现这个波长,不久全世界就都知道了它。","explanation_cn":"it was not long before + 从句;填 know 的过去式 knew。✓ it was not long before the whole world knew about it. ✗ know(原形)/ known / knowing:从句用过去式 knew。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp6','choice','{"stem":"\"In a way that is the only one of its kind is ___.\"(“独特地,唯一地”用哪个词)","options":["roughly","uniquely","rarely","barely"],"answer_index":1,"stem_cn":"以某种独一无二的方式。","explanation_cn":"以独一无二的方式是 uniquely(独特地、唯一地)。✓ in a way that is the only one of its kind is uniquely. ✗ roughly 粗略地;✗ barely 勉强;✗ rarely 很少——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp6','choice','{"stem":"\"Based on reason rather than emotion, an argument is ___.\"(“理性的,合理的”用哪个词)","options":["national","radical","regional","rational"],"answer_index":3,"stem_cn":"基于理性而非情感的。","explanation_cn":"基于理性而非情感的是 rational(理性的、合理的)。✓ based on reason is rational. ✗ national 国家的;✗ radical 激进的;✗ regional 地区的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',5,'am4_l43_gp6','choice','{"stem":"\"The sending out of light, heat, or radio waves is ___.\"(“发射,散发”用哪个词)","options":["permission","emission","commission","admission"],"answer_index":1,"stem_cn":"光、热或无线电波的发出。","explanation_cn":"光、热或无线电波的发出是 emission(发射、散发)。✓ the sending out of waves is emission. ✗ permission 许可;✗ admission 准入;✗ commission 委托——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',6,NULL,'choice','{"stem":"uniquely 的意思是:","options":["独特地,唯一地","勉强地","普遍地","偶然地"],"answer_index":0,"explanation_cn":"uniquely = 独特地、唯一地。✓ a uniquely rational way to signal."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',6,NULL,'choice','{"stem":"rational 的意思是:","options":["地方的","理性的,合理的","激进的","情绪化的"],"answer_index":1,"explanation_cn":"rational = 理性的、合理的。✓ a uniquely rational way."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',6,NULL,'choice','{"stem":"prevailing 的意思是:","options":["罕见的","短暂的","隐藏的","盛行的,当时的"],"answer_index":3,"explanation_cn":"prevailing = 盛行的、当时的。✓ found our prevailing state so primitive."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',6,NULL,'choice','{"stem":"emission 的意思是:","options":["吸收","发射,散发","反射","储存"],"answer_index":1,"explanation_cn":"emission = 发射、散发。✓ this emission was first detected in 1951."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',6,NULL,'choice','{"stem":"interstellar 的意思是:","options":["水下的","地下的","星际的","大气的"],"answer_index":2,"explanation_cn":"interstellar = 星际的。✓ a frequency for interstellar messages."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',6,NULL,'choice','{"stem":"rendezvous 的意思是:","options":["离别","障碍","争吵","会合(地点),约会"],"answer_index":3,"explanation_cn":"rendezvous = 会合(地点)、约会。✓ with no agreed rendezvous."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',7,NULL,'cloze','{"stem":"第 1 空","context":"Given so many worlds, other stars are ___1___ to have planets like ours. Visitors ___2___ have come here long ago. Our rockets cannot reach the nearest star, ___3___ distant galaxies. ___4___ was not long before radio offered a way to call across space.","blank_no":1,"options":["bound","bounded","binding","bind"],"answer_index":0,"explanation_cn":"be bound to do,‘必定/注定要…’;填过去分词 bound。✓ other stars are bound to have planets."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',7,NULL,'cloze','{"stem":"第 2 空","context":"Given so many worlds, other stars are ___1___ to have planets like ours. Visitors ___2___ have come here long ago. Our rockets cannot reach the nearest star, ___3___ distant galaxies. ___4___ was not long before radio offered a way to call across space.","blank_no":2,"options":["may","will","shall","does"],"answer_index":0,"explanation_cn":"对过去的推测‘可能已经…’= may + have + 过去分词;填 may。✓ visitors may have come here long ago."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',7,NULL,'cloze','{"stem":"第 3 空","context":"Given so many worlds, other stars are ___1___ to have planets like ours. Visitors ___2___ have come here long ago. Our rockets cannot reach the nearest star, ___3___ distant galaxies. ___4___ was not long before radio offered a way to call across space.","blank_no":3,"options":["let alone","as well as","rather than","along with"],"answer_index":0,"explanation_cn":"‘更不用说…’用 let alone。✓ cannot reach the nearest star, let alone distant galaxies."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',7,NULL,'cloze','{"stem":"第 4 空","context":"Given so many worlds, other stars are ___1___ to have planets like ours. Visitors ___2___ have come here long ago. Our rockets cannot reach the nearest star, ___3___ distant galaxies. ___4___ was not long before radio offered a way to call across space.","blank_no":4,"options":["It","There","That","This"],"answer_index":0,"explanation_cn":"it was not long before …,‘不久就…’;句首用形式主语 It。✓ It was not long before radio offered a way."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',8,NULL,'choice','{"stem":"What does the ''uniquely rational way'' to communicate across space depend on?","options":["Waiting for aliens to land on Earth","Sending chemical rockets to every star","Building giant telescopes on Mars","A precise natural radio frequency — the 21-cm hydrogen wavelength — that any radio astronomer would know"],"answer_index":3,"explanation_cn":"录音说:唯一合理的方式,靠一个精确的自然射电频率——氢的21厘米波长,任何射电天文学家都会知道。✓ 21-cm hydrogen frequency."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',8,NULL,'choice','{"stem":"Why have we probably had no visitors from outer space yet, according to the passage?","options":["Because intelligent life does not exist elsewhere","The astronomical distances are so vast that even radio waves and rockets cannot easily bridge them","Because Earth is hidden from view","Because visitors are forbidden to land"],"answer_index":1,"explanation_cn":"录音说:至今没有访客,多半因为天文距离太过遥远,连无线电波和火箭都难以跨越。✓ vast distances."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',8,NULL,'choice','{"stem":"Why is Earth thought to be the only planet in our solar system where life can survive?","options":["Because Earth is closest to the sun","Because Earth is the largest planet","The other planets are too dry, too hot, or far too cold with hostile atmospheres","Because the other planets have no moons"],"answer_index":2,"explanation_cn":"录音说:地球是太阳系唯一宜居的行星,别的行星或太干、或太热、或极冷且大气恶劣。✓ others too dry/hot/cold."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',9,NULL,'choice','{"stem":"你想说\"别的恒星必定也有像我们这样的行星\"(be bound to do):","options":["Other stars are bound to have planets like our own.","Other stars are bound having planets like our own.","Other stars bound to have planets like our own.","Other stars are bound to having planets like our own."],"answer_index":0,"explanation_cn":"be bound to do;bound 后接 to have(不用 having、不用 to having)、be 动词不能漏(不写 stars bound to have)。✓ are bound to have. 场合:说“必定/注定要…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',9,NULL,'choice','{"stem":"你想说\"访客可能在数百万年前就来过地球\"(may have done 对过去推测):","options":["Visitors may have came to Earth millions of years ago.","Visitors may came to Earth millions of years ago.","Visitors may have come to Earth millions of years ago.","Visitors may coming to Earth millions of years ago."],"answer_index":2,"explanation_cn":"对过去的推测 may have + 过去分词;用 come 的过去分词 come(不用 came)、不用 coming、have 不能漏(不写 may came)。✓ may have come. 场合:对过去的事作推测。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',9,NULL,'choice','{"stem":"你想说\"我们的火箭连最近的恒星都到不了,更别提遥远的星系\"(let alone):","options":["Our rockets cannot reach the nearest star, let alone reaching distant galaxies.","Our rockets cannot reach the nearest star, let alone to distant galaxies.","Our rockets cannot reach the nearest star, as well as distant galaxies.","Our rockets cannot reach the nearest star, let alone distant galaxies."],"answer_index":3,"explanation_cn":"let alone,‘更不用说…’;后接名词 distant galaxies(不加 to、不用动名词 reaching)、不能换成 as well as(意思相反)。✓ let alone distant galaxies. 场合:说“连…都不…,更不用说…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"uniquely 的意思是:","options":["偶然地","独特地,唯一地","勉强地","普遍地"],"answer_index":1,"explanation_cn":"uniquely = 独特地、唯一地。✓ a uniquely rational way."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"rational 的意思是:","options":["情绪化的","地方的","激进的","理性的,合理的"],"answer_index":3,"explanation_cn":"rational = 理性的、合理的。✓ a uniquely rational way."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"\"Other stars are ___ to have planets like ours.\"(be __ to do 表‘必定’)","options":["bounded","bind","bound","binding"],"answer_index":2,"stem_cn":"别的恒星必定有像我们这样的行星。","explanation_cn":"be bound to do,‘必定…’;填过去分词 bound。✓ are bound to have planets. ✗ bounded / binding / bind。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"\"Visitors ___ have come here millions of years ago.\"(对过去的推测)","options":["may","does","shall","will"],"answer_index":0,"stem_cn":"访客可能在数百万年前来过。","explanation_cn":"对过去的推测‘可能已经…’= may + have + 过去分词;填 may。✓ may have come here. ✗ will / shall / does。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"\"come up against\" 的意思是:","options":["制造…","放弃…","遇到,碰到(困难)","支持…"],"answer_index":2,"explanation_cn":"come up against = 遇到、碰到(困难)。✓ here we come up against the hardest obstacle."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"\"on average\" 的意思是:","options":["从不","立刻","完全地","平均而言"],"answer_index":3,"explanation_cn":"on average = 平均而言。✓ on average, our neighbors might be a hundred light years away."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"Why does the writer think intelligent life is bound to exist elsewhere in the universe?","options":["Because scientists have already met aliens","Because Earth is unique","The number of planets is so vast that even a tiny fraction developing life makes it a natural part of the universe","Because life is easy to create"],"answer_index":2,"passage":"From the work of those who have studied the origin of life, we must conclude that, given a planet only roughly like our own, life is almost certain to begin. Of all the planets in our solar system, we are now fairly sure that the Earth is the only one on which life can survive. Mars is too dry and poor in oxygen, Venus and Mercury are far too hot, and the outer planets lie near absolute zero, wrapped in hostile atmospheres of hydrogen. But other suns, as astronomers call the stars, are bound to have planets like our own, and since the number of stars is so vast, this mere possibility becomes a virtual certainty. There are a hundred thousand million stars in our own galaxy alone, and the total in the universe is now put at some three hundred million million. Although perhaps only one per cent of the life that begins somewhere will ever develop into complex, intelligent patterns, so vast is the number of planets that intelligent life is bound to be a natural part of the universe. If, then, we are so certain that other minds exist, why have we had no visitors from outer space? First, they may have come to this planet thousands, or even millions, of years ago, and found our prevailing state so primitive that it held no interest for their advanced knowledge. A superior civilization, on a brief visit to our solar system, may well have left an automatic messenger behind, to await the possible awakening of a more advanced people. Here, however, we come up against the most difficult of all obstacles: the astronomical distances that separate us. On average, our neighbors might be a hundred light years away — and a light year is the distance light travels in a year, at a hundred and eighty-six thousand miles a second. Our present chemical rockets, good enough to carry people into orbit, have no chance of reaching even the nearest other star, four light years away, let alone distances of tens or hundreds of light years. Fortunately, as one science writer has put it in a well-known book, there is a uniquely rational way for us to signal to other intelligent beings. It depends on one exact radio frequency: the 21-cm wavelength, or 1420 megacycles a second, naturally given off by the hydrogen atoms that drift through space. This emission was first detected here in 1951, and it must be known to any radio astronomer anywhere in the universe. Once the wavelength had been found, it was not long before someone proposed using it as the one clearly recognizable frequency for interstellar messages. Without something of this kind, searching for minds on other worlds would be like trying to meet a friend in a huge city with no agreed rendezvous, wandering the streets forever in the hope of a chance encounter.","explanation_cn":"课文说:行星数目如此之多,即便只有极小一部分孕育出生命,智慧生命也必然是宇宙的自然一部分。✓ vast number of planets."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"What is the greatest obstacle to actually contacting other civilizations?","options":["The danger of the journey","The lack of any common language","The cost of radios","The immense astronomical distances that separate the stars"],"answer_index":3,"passage":"From the work of those who have studied the origin of life, we must conclude that, given a planet only roughly like our own, life is almost certain to begin. Of all the planets in our solar system, we are now fairly sure that the Earth is the only one on which life can survive. Mars is too dry and poor in oxygen, Venus and Mercury are far too hot, and the outer planets lie near absolute zero, wrapped in hostile atmospheres of hydrogen. But other suns, as astronomers call the stars, are bound to have planets like our own, and since the number of stars is so vast, this mere possibility becomes a virtual certainty. There are a hundred thousand million stars in our own galaxy alone, and the total in the universe is now put at some three hundred million million. Although perhaps only one per cent of the life that begins somewhere will ever develop into complex, intelligent patterns, so vast is the number of planets that intelligent life is bound to be a natural part of the universe. If, then, we are so certain that other minds exist, why have we had no visitors from outer space? First, they may have come to this planet thousands, or even millions, of years ago, and found our prevailing state so primitive that it held no interest for their advanced knowledge. A superior civilization, on a brief visit to our solar system, may well have left an automatic messenger behind, to await the possible awakening of a more advanced people. Here, however, we come up against the most difficult of all obstacles: the astronomical distances that separate us. On average, our neighbors might be a hundred light years away — and a light year is the distance light travels in a year, at a hundred and eighty-six thousand miles a second. Our present chemical rockets, good enough to carry people into orbit, have no chance of reaching even the nearest other star, four light years away, let alone distances of tens or hundreds of light years. Fortunately, as one science writer has put it in a well-known book, there is a uniquely rational way for us to signal to other intelligent beings. It depends on one exact radio frequency: the 21-cm wavelength, or 1420 megacycles a second, naturally given off by the hydrogen atoms that drift through space. This emission was first detected here in 1951, and it must be known to any radio astronomer anywhere in the universe. Once the wavelength had been found, it was not long before someone proposed using it as the one clearly recognizable frequency for interstellar messages. Without something of this kind, searching for minds on other worlds would be like trying to meet a friend in a huge city with no agreed rendezvous, wandering the streets forever in the hope of a chance encounter.","explanation_cn":"课文说:真正与外星文明接触的最大障碍,是把恒星隔开的巨大天文距离。✓ astronomical distances."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"What natural radio frequency could serve as a common ''call sign'' across space?","options":["The sound of the sun","A signal only humans can detect","The 21-cm wavelength emitted by hydrogen atoms, known to every radio astronomer","A frequency invented on Earth in the 1920s"],"answer_index":2,"audio":"From the work of those who have studied the origin of life, we must conclude that, given a planet only roughly like our own, life is almost certain to begin. Of all the planets in our solar system, we are now fairly sure that the Earth is the only one on which life can survive. Mars is too dry and poor in oxygen, Venus and Mercury are far too hot, and the outer planets lie near absolute zero, wrapped in hostile atmospheres of hydrogen. But other suns, as astronomers call the stars, are bound to have planets like our own, and since the number of stars is so vast, this mere possibility becomes a virtual certainty. There are a hundred thousand million stars in our own galaxy alone, and the total in the universe is now put at some three hundred million million. Although perhaps only one per cent of the life that begins somewhere will ever develop into complex, intelligent patterns, so vast is the number of planets that intelligent life is bound to be a natural part of the universe. If, then, we are so certain that other minds exist, why have we had no visitors from outer space? First, they may have come to this planet thousands, or even millions, of years ago, and found our prevailing state so primitive that it held no interest for their advanced knowledge. A superior civilization, on a brief visit to our solar system, may well have left an automatic messenger behind, to await the possible awakening of a more advanced people. Here, however, we come up against the most difficult of all obstacles: the astronomical distances that separate us. On average, our neighbors might be a hundred light years away — and a light year is the distance light travels in a year, at a hundred and eighty-six thousand miles a second. Our present chemical rockets, good enough to carry people into orbit, have no chance of reaching even the nearest other star, four light years away, let alone distances of tens or hundreds of light years. Fortunately, as one science writer has put it in a well-known book, there is a uniquely rational way for us to signal to other intelligent beings. It depends on one exact radio frequency: the 21-cm wavelength, or 1420 megacycles a second, naturally given off by the hydrogen atoms that drift through space. This emission was first detected here in 1951, and it must be known to any radio astronomer anywhere in the universe. Once the wavelength had been found, it was not long before someone proposed using it as the one clearly recognizable frequency for interstellar messages. Without something of this kind, searching for minds on other worlds would be like trying to meet a friend in a huge city with no agreed rendezvous, wandering the streets forever in the hope of a chance encounter.","explanation_cn":"课文说:氢原子发出的21厘米波长,是任何射电天文学家都懂的自然频率,可作共同的‘呼号’。✓ 21-cm hydrogen wavelength."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l43',10,NULL,'choice','{"stem":"Without an agreed frequency, what would searching for other intelligences be like?","options":["Calling a known phone number","Trying to meet a friend in a big city with no arranged place, wandering the streets by chance","Following a straight road","Reading a clear map"],"answer_index":1,"audio":"From the work of those who have studied the origin of life, we must conclude that, given a planet only roughly like our own, life is almost certain to begin. Of all the planets in our solar system, we are now fairly sure that the Earth is the only one on which life can survive. Mars is too dry and poor in oxygen, Venus and Mercury are far too hot, and the outer planets lie near absolute zero, wrapped in hostile atmospheres of hydrogen. But other suns, as astronomers call the stars, are bound to have planets like our own, and since the number of stars is so vast, this mere possibility becomes a virtual certainty. There are a hundred thousand million stars in our own galaxy alone, and the total in the universe is now put at some three hundred million million. Although perhaps only one per cent of the life that begins somewhere will ever develop into complex, intelligent patterns, so vast is the number of planets that intelligent life is bound to be a natural part of the universe. If, then, we are so certain that other minds exist, why have we had no visitors from outer space? First, they may have come to this planet thousands, or even millions, of years ago, and found our prevailing state so primitive that it held no interest for their advanced knowledge. A superior civilization, on a brief visit to our solar system, may well have left an automatic messenger behind, to await the possible awakening of a more advanced people. Here, however, we come up against the most difficult of all obstacles: the astronomical distances that separate us. On average, our neighbors might be a hundred light years away — and a light year is the distance light travels in a year, at a hundred and eighty-six thousand miles a second. Our present chemical rockets, good enough to carry people into orbit, have no chance of reaching even the nearest other star, four light years away, let alone distances of tens or hundreds of light years. Fortunately, as one science writer has put it in a well-known book, there is a uniquely rational way for us to signal to other intelligent beings. It depends on one exact radio frequency: the 21-cm wavelength, or 1420 megacycles a second, naturally given off by the hydrogen atoms that drift through space. This emission was first detected here in 1951, and it must be known to any radio astronomer anywhere in the universe. Once the wavelength had been found, it was not long before someone proposed using it as the one clearly recognizable frequency for interstellar messages. Without something of this kind, searching for minds on other worlds would be like trying to meet a friend in a huge city with no agreed rendezvous, wandering the streets forever in the hope of a chance encounter.","explanation_cn":"课文说:没有约定频率地搜寻外星心智,就像在大城市里没有约定地点找朋友,只能在街上碰运气。✓ meeting a friend with no rendezvous."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l44',4,8,44,'Patterns of Culture','文化模式','no matter how(无论多么…)、by the time(到…时候)、require/demand that + (should) 动词原形(虚拟语气)、as long as(只要)、see/feel/want + 名词 + done/to be(感官认知动词的复合结构)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为 Ruth Benedict《Patterns of Culture》一段论习俗对人塑造的人类学随笔,系版权作品——已用 100% 原创行文复述其观点、无引用原句;具名 John Dewey 已泛化为‘一位知名哲学家’;题材=人类学·无害;美语化 color/neighbor;第四册第44课)','习俗通常不被看作一个重要的话题。我们觉得自己头脑内部的运作独一无二地值得研究,而习俗,我们往往以为,不过是行为中最平常的那一类。事实上恰恰相反。放眼全世界,传统习俗是一大堆细致入微的行为,比任何一个人凭一己之力所能发明的、无论多么离经叛道的东西,都更令人惊叹。可这只是这件事微不足道的一面。真正头等重要的,是习俗在我们的经验与信念中所占的主导地位,以及它可能呈现的极大的多样性。没有人是用全然崭新的眼睛去看世界的。他所看到的世界,早已被一整套固定的习俗、制度和思维方式剪裁过了。哪怕在他最深的追问里,他也无法绕到这些成见的背后;他关于真与假的观念本身,仍旧要回溯到他自己那一套传统。一位知名的哲学家曾一本正经地说过:习俗在塑造一个人时所起的作用,相比他本人所能给这套习俗添上的东西,就像他母语的全部词汇相比他自己婴儿牙牙学语时、恰好被家人拾起的那几个词。从出生的那一刻起,一个孩子所生入的习俗,就在塑造他的经验和行为。到他会说话时,他已是自己文化的小小造物;到他长大、能参与文化的种种活动时,文化的习惯已成了他的习惯,文化的信念已成了他的信念。每个生入某个群体的孩子都会渐渐分享这些,而生在地球另一端的孩子,连其千分之一都无从达到。没有哪个社会问题比理解习俗的这一作用更是我们义不容辞该弄懂的。然而,对习俗的研究,只有在若干预备性的命题被接受之后才可能有成效——而其中有些命题曾遭到激烈的反对。任何科学研究都要求:在它所考察的各个项目之间,不能有偏向性的加权。在争议较少的领域里,方法不过是把一切相关材料收集起来,记下每一种可能的变体形式;正是这样,我们才懂得了天文学、懂得了群居昆虫的种种。只要‘我们’与野蛮人、‘我们’与异教徒之间那些旧的区分还左右着人们的头脑,人类学按其定义本身就是不可能的。必须首先走到这一步:我们不再拿自己的信仰去对抗邻人的迷信,并且认清所有这类制度都必须被放在一起、连同我们自己的一并加以考察。','{"q":"Listen and answer — What influences us from the moment of birth?","options":["The customs of the community into which we are born","The stars we were born under","The books we later choose to read","Our own private inventions"],"answer_index":0}'::jsonb,'{"title":"no matter how / by the time / require that + 原形 / as long as / see·feel + 名词 + done·to be","intro":"①no matter how + 形容词/副词:‘无论多么…’。②by the time:‘到…时候’,主句常用完成时。③require/demand/suggest that + (should) + 动词原形:虚拟语气。④as long as:‘只要…(就)’,引导条件。⑤see/feel/want + 名词 + 过去分词/to be:感官或认知动词的复合结构。","table":{"headers":["用法","结构","例子"],"rows":[["no matter how","no matter how + 形/副","no matter how aberrant"],["by the time","By the time + 从句, 主句完成时","By the time he can talk, …"],["require that + 原形","require that + (should) 原形","requires that there be no weighting"],["as long as","as long as + 从句","as long as prejudices held sway"],["see + 名词 + done","see/feel/want + 名词 + 过去分词","he sees it edited by custom"]]},"specialRules":[{"rule":"require/demand/insist/suggest/order 等后接 that 从句,谓语用‘(should) + 动词原形’,不随主句变化。","mark":"require that + 原形"},{"rule":"by the time 引导的时间从句,主句常用完成时:现在完成(现在)或过去完成(过去)。","mark":"By the time …, had done"},{"rule":"美式拼写:color(颜色,英式 colour)、neighbor(邻居,英式 neighbour)。本课已按美语写。","mark":"color / neighbor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l44',1,NULL,'Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant.','习俗通常不被看作一个重要的话题。我们觉得自己头脑内部的运作独一无二地值得研究,而习俗,我们往往以为,不过是行为中最平常的那一类。事实上恰恰相反。放眼全世界,传统习俗是一大堆细致入微的行为,比任何一个人凭一己之力所能发明的、无论多么离经叛道的东西,都更令人惊叹。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l44',2,NULL,'Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking.','可这只是这件事微不足道的一面。真正头等重要的,是习俗在我们的经验与信念中所占的主导地位,以及它可能呈现的极大的多样性。没有人是用全然崭新的眼睛去看世界的。他所看到的世界,早已被一整套固定的习俗、制度和思维方式剪裁过了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l44',3,NULL,'Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up.','哪怕在他最深的追问里,他也无法绕到这些成见的背后;他关于真与假的观念本身,仍旧要回溯到他自己那一套传统。一位知名的哲学家曾一本正经地说过:习俗在塑造一个人时所起的作用,相比他本人所能给这套习俗添上的东西,就像他母语的全部词汇相比他自己婴儿牙牙学语时、恰好被家人拾起的那几个词。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l44',4,NULL,'From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part.','从出生的那一刻起,一个孩子所生入的习俗,就在塑造他的经验和行为。到他会说话时,他已是自己文化的小小造物;到他长大、能参与文化的种种活动时,文化的习惯已成了他的习惯,文化的信念已成了他的信念。每个生入某个群体的孩子都会渐渐分享这些,而生在地球另一端的孩子,连其千分之一都无从达到。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l44',5,NULL,'The study of custom can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary to recognize that all such institutions must be considered together, our own among the rest.','然而,对习俗的研究,只有在若干预备性的命题被接受之后才可能有成效——而其中有些命题曾遭到激烈的反对。任何科学研究都要求:在它所考察的各个项目之间,不能有偏向性的加权。只要‘我们’与野蛮人、‘我们’与异教徒之间那些旧的区分还左右着人们的头脑,人类学按其定义本身就是不可能的。必须认清:所有这类制度都必须被放在一起、连同我们自己的一并加以考察。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
