INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','take part in','',NULL,'/teɪk pɑːrt ɪn/','By the time he is grown, he can take part in its activities.','到他长大时,他就能参与文化的种种活动。','She took part in the debate.','她参加了那场辩论。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','hold sway over','',NULL,'/hoʊld sweɪ ˈoʊvər/','Old distinctions held sway over people''s minds.','旧的区分左右着人们的头脑。','Fashion holds sway over the young.','时尚左右着年轻人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','the other way around','',NULL,'/ðə ˈʌðər weɪ əˈraʊnd/','As a matter of fact, it is the other way around.','事实上,恰恰相反。','I thought he was older, but it''s the other way around.','我以为他更大,其实正好反过来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','as a matter of fact','',NULL,'/æz ə ˈmætər ʌv fækt/','As a matter of fact, custom is not commonplace at all.','事实上,习俗根本不是什么平常的东西。','As a matter of fact, I agree with you.','事实上,我同意你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp1','choice','{"stem":"\"Custom shapes us, ___ how strange an individual''s own actions may be.\"(‘无论多么…’,填引导让步的词组)","options":["as if","no matter","even if","in case"],"answer_index":1,"stem_cn":"无论个人自己的行为多么古怪,习俗都在塑造着我们。","explanation_cn":"‘无论多么…’= no matter how + 形容词;填 no matter。✓ no matter how strange … may be. ✗ even if 即使 / as if 好像 / in case 以防:‘无论多么’用 no matter how。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp1','choice','{"stem":"\"___ how carefully he probes, he cannot escape his own stereotypes.\"(‘无论多么…’,填让步词组)","options":["Even if","In case","As if","No matter"],"answer_index":3,"stem_cn":"无论他探究得多么仔细,都摆脱不了自己的成见。","explanation_cn":"‘无论多么…’用 No matter how。✓ No matter how carefully he probes … ✗ Even if / As if / In case:‘无论多么’用 No matter how。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp1','choice','{"stem":"\"The child absorbs its culture, no matter ___ far away it was born.\"(no matter ___ 结构,填表‘多么’的那个词)","options":["that","how","what","which"],"answer_index":1,"stem_cn":"无论孩子生在多远的地方,都会吸收自己的文化。","explanation_cn":"no matter how + 形容词/副词;填表‘多么’的 how。✓ no matter how far away it was born. ✗ what / which / that:‘无论多么…’用 how。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp2','choice','{"stem":"\"___ the time a child can talk, he is the creature of his culture.\"(‘到…时候’,填引导时间从句的词)","options":["On","At","By","In"],"answer_index":2,"stem_cn":"到孩子会说话时,他已是自己文化的产物。","explanation_cn":"‘到…时候’= By the time;填 By。✓ By the time a child can talk … ✗ At / In / On:‘到…时候’用 By the time。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp2','choice','{"stem":"\"By the time he is grown, its beliefs ___ become his own.\"(by the time + 主句常用完成时,填助动词)","options":["will","do","are","have"],"answer_index":3,"stem_cn":"到他长大时,那些信仰已成了他自己的。","explanation_cn":"by the time 引导时间从句,主句常用完成时;主语 beliefs 复数用 have。✓ its beliefs have become his own. ✗ are / will / do:此处用现在完成 have become。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp2','choice','{"stem":"\"By the time we noticed, the custom ___ already shaped our thinking.\"(by the time + 过去,主句用过去完成,填助动词)","options":["had","has","does","will"],"answer_index":0,"stem_cn":"等我们察觉时,习俗早已塑造了我们的思维。","explanation_cn":"by the time 从句为过去,主句用过去完成;填 had。✓ the custom had already shaped our thinking. ✗ has / will / does:此处用过去完成 had shaped。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp3','choice','{"stem":"\"Any scientific study requires that there ___ no preferential weighting of the items.\"(require that 后从句用动词原形,填 there ___ 里那个原形)","options":["is","are","be","was"],"answer_index":2,"stem_cn":"任何科学研究都要求各项目之间没有偏向性的加权。","explanation_cn":"require that + 从句谓语用(should)动词原形;there be 结构填原形 be。✓ requires that there be no weighting. ✗ is / was / are:虚拟语气用原形 be。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp3','choice','{"stem":"\"The method demands that each variant form ___ noted.\"(demand that 后从句用原形;被动‘___ noted’,填最前那个原形)","options":["being","be","is","was"],"answer_index":1,"stem_cn":"这方法要求每一种变体形式都被记录下来。","explanation_cn":"demand that + 从句用(should)动词原形;被动 be + 过去分词,填原形 be。✓ demands that each form be noted. ✗ is / was / being:虚拟语气用原形 be。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp3','choice','{"stem":"\"He suggested that the researcher ___ set his own belief above others.\"(suggest that + (should) 原形,填‘应当不’里那个否定词)","options":["did not","is not","not","does not"],"answer_index":2,"stem_cn":"他建议研究者不要把自己的信仰凌驾于他人之上。","explanation_cn":"suggest that + (should) 动词原形;否定直接在原形前加 not(should not set)。✓ suggested that the researcher not set … ✗ does not / did not / is not:虚拟否定用 (should) not + 原形。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp4','choice','{"stem":"\"Anthropology was impossible ___ these prejudices held sway over people''s minds.\"(‘只要…’,填引导条件的词组)","options":["as soon as","as far as","as well as","as long as"],"answer_index":3,"stem_cn":"只要这些偏见还左右着人们的头脑,人类学就不可能存在。","explanation_cn":"‘只要…’引导条件用 as long as。✓ as long as these prejudices held sway. ✗ as soon as 一…就 / as well as 以及 / as far as 就…而言:‘只要’用 as long as。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp4','choice','{"stem":"\"We can understand other peoples ___ we stop judging them by our own customs.\"(‘只要…就…’,填条件词组)","options":["as long as","as soon as","as well as","as if"],"answer_index":0,"stem_cn":"只要我们不再用自己的习俗去评判别人,就能理解他们。","explanation_cn":"‘只要…就…’用 as long as。✓ as long as we stop judging them. ✗ as soon as / as well as / as if:‘只要’用 as long as。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp4','choice','{"stem":"\"Custom will rule us ___ we remain ignorant of its laws.\"(‘只要…’,填条件词组)","options":["as though","as many as","as long as","as much as"],"answer_index":2,"stem_cn":"只要我们对习俗的规律一无所知,它就会支配我们。","explanation_cn":"‘只要…’用 as long as。✓ as long as we remain ignorant. ✗ as though / as many as / as much as:‘只要’用 as long as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp5','choice','{"stem":"\"No one looks at the world freshly; he sees it ___ by his customs.\"(see + 名词 + 过去分词,填‘剪裁/编辑’那个动词的过去分词)","options":["to edit","edited","editing","edit"],"answer_index":1,"stem_cn":"没有人以全新的眼光看世界;他看到的世界已被自己的习俗剪裁过。","explanation_cn":"see + 名词 + 过去分词(表被动完成);填 edit 的过去分词 edited。✓ he sees it edited by his customs. ✗ editing / edit / to edit:此处宾语与动作是被动,用过去分词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp5','choice','{"stem":"\"We feel the workings of our own minds ___ be worthy of study.\"(feel + 名词 + 不定式,填不定式最前面的记号)","options":["to","that","of","/"],"answer_index":0,"stem_cn":"我们觉得自己头脑的运作值得研究。","explanation_cn":"feel + 名词 + 不定式(feel sth to be…);填不定式记号 to。✓ we feel the workings to be worthy. ✗ 省略 / that / of:feel sth to be 结构用 to。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp5','choice','{"stem":"\"Every community wants its beliefs ___ by the young.\"(want + 名词 + 过去分词,填‘尊重’那个动词的过去分词)","options":["respecting","respect","respected","to respect"],"answer_index":2,"stem_cn":"每个族群都希望自己的信仰被年轻人所尊重。","explanation_cn":"want + 名词 + 过去分词(want sth done);填 respect 的过去分词 respected。✓ wants its beliefs respected. ✗ respecting / respect / to respect:被动完成用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp6','choice','{"stem":"\"Something ordinary and not at all remarkable is ___.\"(“平凡的,普通的”用哪个词)","options":["commonplace","commonwealth","commonly","commonsense"],"answer_index":0,"stem_cn":"平常、毫不起眼的。","explanation_cn":"平常、毫不起眼的是 commonplace(平凡的、普通的)。✓ ordinary and not remarkable is commonplace. ✗ commonwealth 联邦;✗ commonsense 常识;✗ commonly 通常(副词)——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp6','choice','{"stem":"\"Something of very little importance or value is ___.\"(“琐碎的,微不足道的”用哪个词)","options":["crucial","trivial","initial","radical"],"answer_index":1,"stem_cn":"极不重要或没什么价值的。","explanation_cn":"极不重要或没什么价值的是 trivial(琐碎的、微不足道的)。✓ of very little importance is trivial. ✗ crucial 关键的;✗ radical 激进的;✗ initial 最初的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp6','choice','{"stem":"\"To show or display something clearly is to ___ it.\"(“表明,显示”用哪个词)","options":["magnify","memorize","manifest","minimize"],"answer_index":2,"stem_cn":"清楚地展示或表现某物。","explanation_cn":"清楚地展示或表现某物是 manifest(表明、显示)。✓ to show something clearly is to manifest it. ✗ minimize 使最小化;✗ memorize 记住;✗ magnify 放大——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"commonplace 的意思是:","options":["复杂的","珍贵的","平凡的,普通的","罕见的"],"answer_index":2,"explanation_cn":"commonplace = 平凡的、普通的。✓ behavior at its most commonplace."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"aberrant 的意思是:","options":["反常的,越轨的","普通的","正常的","温和的"],"answer_index":0,"explanation_cn":"aberrant = 反常的、越轨的。✓ no matter how aberrant."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"trivial 的意思是:","options":["巨大的","重要的","严重的","琐碎的,微不足道的"],"answer_index":3,"explanation_cn":"trivial = 琐碎的、微不足道的。✓ only a trivial side of the matter."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"predominant 的意思是:","options":["占主导地位的,显著的","微弱的","次要的","隐藏的"],"answer_index":0,"explanation_cn":"predominant = 占主导地位的、显著的。✓ the predominant part that custom plays."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"pristine 的意思是:","options":["陈旧的","肮脏的","崭新的,未受污染的","受损的"],"answer_index":2,"explanation_cn":"pristine = 崭新的、未受污染的。✓ with wholly pristine eyes."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"stereotype 的意思是:","options":["成见,刻板印象","证据","事实","例外"],"answer_index":0,"explanation_cn":"stereotype = 成见、刻板印象。✓ he cannot get behind these stereotypes."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 1 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":1,"options":["how","what","which","that"],"answer_index":0,"explanation_cn":"no matter how + 形容词;填 how。✓ No matter how strange his neighbor''s ways may seem …"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 2 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":2,"options":["By","At","In","On"],"answer_index":0,"explanation_cn":"‘到…时候’= By the time;填 By。✓ By the time a child can talk, he belongs to his culture."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 3 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":3,"options":["be","is","was","are"],"answer_index":0,"explanation_cn":"require/demand that + 从句用(should)动词原形;填 be。✓ demands that no item be given special weight."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 4 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":4,"options":["as long as","as soon as","as well as","as far as"],"answer_index":0,"explanation_cn":"‘只要…’引导条件用 as long as。✓ Prejudice ruled us as long as we kept judging others."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',8,NULL,'choice','{"stem":"What shapes a person''s experience and behavior from the very moment of birth?","options":["The stars he was born under","The customs of the community into which he is born","His own private inventions","The books he later reads"],"answer_index":1,"explanation_cn":"录音说:从出生那一刻起,一个人生入的社群习俗就在塑造他的经验与行为。✓ customs of his community."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',8,NULL,'choice','{"stem":"Why does the writer say no one looks at the world with ''pristine eyes''?","options":["Because we always see it already edited by our customs, institutions and ways of thinking","Because we are born blind to custom","Because our eyesight is weak","Because the world is too complex"],"answer_index":0,"explanation_cn":"录音说:没有人用全新的眼睛看世界,我们看到的都是被习俗、制度和思维方式剪裁过的世界。✓ world edited by custom."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',8,NULL,'choice','{"stem":"What did the study of man wrongly do for a long time, according to the passage?","options":["It ignored Western civilization completely","It studied only cacti and termites","It treated one local variation — Western civilization — as if it were the whole story","It refused to group any material"],"answer_index":2,"explanation_cn":"录音说:长久以来,对人的研究把西方文明这一局部变体当成了全部。✓ Western civilization as the whole."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',9,NULL,'choice','{"stem":"你想说\"无论个人的行为多么古怪,习俗都在塑造我们\"(no matter how):","options":["How aberrant an individual''s actions are, no matter custom shapes us.","No matter what aberrant an individual''s actions are, custom shapes us.","No matter how aberrant an individual''s actions are, but custom shapes us.","No matter how aberrant an individual''s actions are, custom shapes us."],"answer_index":3,"explanation_cn":"no matter how + 形容词;主句不再加 but(不写 …, but custom)、how 后接形容词(不用 what)、no matter how 须在句首整体引导。✓ No matter how aberrant …, … 场合:说“无论多么…都…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',9,NULL,'choice','{"stem":"你想说\"到孩子会说话时,他已是自己文化的产物\"(by the time):","options":["By a child can talk, he is the creature of his culture.","By the time a child can talk, he is the creature of his culture.","Until the time a child can talk, he is the creature of his culture.","By the time a child can talk, he was the creature of his culture."],"answer_index":1,"explanation_cn":"by the time 引导时间从句;主句时态一致用 is(不写 was)、不能换 Until(义不同)、不能省 the time(不写 By a child can talk)。✓ By the time …, … 场合:说“到…时候(已经)…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',9,NULL,'choice','{"stem":"你想说\"只要这些偏见还左右着人们的头脑,人类学就不可能存在\"(as long as):","options":["As soon as these prejudices held sway over people''s minds, anthropology was impossible.","As far as these prejudices held sway over people''s minds, anthropology was impossible.","As long as these prejudices held sway over people''s minds, anthropology was impossible.","As long as these prejudices held sway over people''s minds, but anthropology was impossible."],"answer_index":2,"explanation_cn":"as long as 引导条件‘只要’;不用 as soon as(义不同)、主句不再加 but、不用 as far as。✓ As long as …, … 场合:说“只要…(就)…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"commonplace 的意思是:","options":["罕见的","珍贵的","复杂的","平凡的,普通的"],"answer_index":3,"explanation_cn":"commonplace = 平凡的、普通的。✓ behavior at its most commonplace."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"trivial 的意思是:","options":["琐碎的,微不足道的","巨大的","重要的","严重的"],"answer_index":0,"explanation_cn":"trivial = 琐碎的、微不足道的。✓ only a trivial side of the matter."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"___ the time a child can talk, he belongs to his culture.\"(‘到…时候’引导时间从句)","options":["At","In","On","By"],"answer_index":3,"stem_cn":"到孩子会说话时,他已属于自己的文化。","explanation_cn":"‘到…时候’= By the time;填 By。✓ By the time a child can talk … ✗ At / In / On。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"Science requires that each item ___ treated equally.\"(require that + 从句用动词原形)","options":["is","was","be","are"],"answer_index":2,"stem_cn":"科学要求每一项都被平等对待。","explanation_cn":"require that + 从句用(should)动词原形;填 be。✓ requires that each item be treated equally. ✗ is / was / are。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"take part in\" 的意思是:","options":["分开…","反对…","拿走…","参加,参与"],"answer_index":3,"explanation_cn":"take part in = 参加、参与。✓ able to take part in its activities."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"hold sway over\" 的意思是:","options":["远离…","依赖…","支配,左右","忽视…"],"answer_index":2,"explanation_cn":"hold sway over = 支配、左右。✓ old distinctions held sway over people''s minds."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"According to the writer, how important is the role of custom in human life?","options":["It affects only primitive peoples","It matters only to anthropologists","It plays almost no part at all","It plays a predominant role in our experience and belief, far greater than most people assume"],"answer_index":3,"passage":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:习俗在我们的经验与信念中起主导作用,远比多数人所以为的大。✓ predominant role of custom."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"What must we accept before the study of custom can be profitable?","options":["That custom cannot be studied scientifically","That no one people''s customs — including our own — should be given special weight over others","That Western civilization is the model for all","That only our own customs are worth studying"],"answer_index":1,"passage":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:研究要有成效,须先接受:任何一族的习俗(包括我们自己的)都不应比别的更受偏重。✓ no preferential weighting."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"By the time a child is grown, whose habits and beliefs does he hold?","options":["Habits he invented by himself","The habits of a distant foreign people","No habits or beliefs at all","Those of his own culture, which have become entirely his own"],"answer_index":3,"audio":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:到孩子长大时,文化的习惯与信念已彻底成了他自己的。✓ culture''s habits become his own."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"What made anthropology possible at last?","options":["Recognizing that our own institutions must be studied together with all others, on the same terms","Setting our beliefs against others'' superstitions","Abandoning the study of custom","Proving Western customs were best"],"answer_index":0,"audio":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:人类学之所以终于可能,在于认清我们自己的制度必须与所有别的制度放在一起、以同样的标准来研究。✓ study all institutions together."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
